#include <iostream>
#include <iomanip>

int main() {
    int total = 0;
    unsigned int counter = 0;
    int grade = 0;

    std::cout << "Enter grade, -1 to end: ";
    if (std::cin >> grade && grade != -1) {
        while (grade != -1) {
            total += grade;
            ++counter;
            std::cout << "Enter grade, -1 to end: ";
            if (!(std::cin >> grade)) {
                break;
            }
        }
    }

    if (counter != 0) {
        // Modern C++ explicit cast to avoid integer division truncation
        double average = static_cast<double>(total) / counter;
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "Class average is " << average << "\n";
    } else {
        std::cout << "No grades were entered\n";
    }

    return 0;
}

#include <iostream>

int main() {
    // Phase 1: Initialization
    unsigned int passes = 0;
    unsigned int failures = 0;
    unsigned int studentCounter = 1;

    // Phase 2: Processing with nested if...else inside while
    while (studentCounter <= 10) {
        std::cout << "Enter result: ";
        int result = 0;
        if (std::cin >> result) {
            if (result == 1) {
                passes = passes + 1;
            } else {
                failures = failures + 1;
            }
            studentCounter = studentCounter + 1;
        } else {
            break;
        }
    }

    // Phase 3: Termination
    std::cout << "Passed " << passes << "\n";
    std::cout << "Failed " << failures << "\n";

    if (passes > 8) {
        std::cout << "Bonus to instructor!\n";
    }

    return 0;
}
